<script setup>import {useForm} from '@inertiajs/vue3'; import AppLayout from '../../../Layouts/AppLayout.vue'; const props=defineProps({account:Object,parents:Array,types:Object,editing:Boolean,endpoints:Object}); const form=useForm({code:props.account.code||'',name:props.account.name||'',description:props.account.description||'',type:props.account.type||'asset',parent_id:props.account.parent_id||'',is_postable:props.account.is_postable??true,is_active:props.account.is_active??true}); const submit=()=>form.transform(d=>props.editing?{...d,_method:'put'}:d).post(props.endpoints.save);</script>
<template><AppLayout :title="editing?'Editar cuenta':'Nueva cuenta'" eyebrow="Contabilidad"><form class="card max-w-3xl p-5" @submit.prevent="submit"><div class="grid gap-4 md:grid-cols-2"><label class="field-label">Código *<input v-model="form.code" class="control"></label><label class="field-label">Nombre *<input v-model="form.name" class="control"></label><label class="field-label">Tipo<select v-model="form.type" class="control"><option v-for="(label,key) in types" :key="key" :value="key">{{label}}</option></select></label><label class="field-label">Cuenta padre<select v-model="form.parent_id" class="control"><option value="">Sin padre</option><option v-for="parent in parents" :key="parent.id" :value="parent.id">{{parent.code}} · {{parent.name}}</option></select></label><label class="field-label md:col-span-2">Descripción<textarea v-model="form.description" class="control"></textarea></label><label class="text-xs"><input v-model="form.is_postable" type="checkbox"> Admite movimientos</label><label class="text-xs"><input v-model="form.is_active" type="checkbox"> Activa</label></div><p v-if="Object.keys(form.errors).length" class="mt-3 text-xs text-rose-600">{{Object.values(form.errors).join(' · ')}}</p><div class="mt-5 flex gap-2"><a :href="endpoints.index" class="btn-secondary">Cancelar</a><button class="btn-primary">Guardar cuenta</button></div></form></AppLayout></template>
